import sizes from "@/content/media-sizes.json";

export type Photo = { src: string; w: number; h: number; caption?: string };

const table: Record<string, number[]> = sizes;

/** Uploads carry their size in the name: /media/uploads/2026/name-1a2b3c4d-1600x1200.webp. */
const uploadSize = (src: string) => src.match(/-(\d+)x(\d+)\.webp$/)?.slice(1, 3).map(Number);

/**
 * Attach the intrinsic size of a photo: from the table generated by scripts/prepare-media.mjs, or from
 * the name of an upload. Any other file gets a 4:3 placeholder size rather than breaking the page.
 */
export function photo(src: string, caption?: string): Photo {
  const size = table[src] ?? uploadSize(src) ?? [1600, 1200];
  return { src, w: size[0], h: size[1], caption };
}

export const photos = (srcs: string[]) => srcs.map((s) => photo(s));
